PTVL_T_CART = 2122       -- cart NPC index
PTVL_T_CARTID = 2124     -- cart NPC id (normalised)
PTVL_T_DEADLINE = 2125   -- LocalSystemTime deadline
PTVL_T_DAY = 2126        -- day of the counter below
PTVL_T_RUNS = 2127       -- runs accepted today
PTVL_T_KILLS = 2128      -- bandits killed this run
PTVL_T_MODE = 2129       -- 1 main road (safe), 2 short cut (ambushes)
PTVL_T_VTCART = 2130     -- Van Tieu cart NPC index
