-- cart params: 0 magic, 1 owner PlayerIndex, 2 owner uuid, 3 deadline, 4 ambush waves, 5 start distance^2,
-- 6 seconds without owner, 7/8 last cell, 9 kind (1 luong, 2 tieu), 10 mode, 11 siege index, 12 arrival hint,
-- 13/14 destination cell, 15 stuck counter
-- bandit params: 0 magic, 1 cart index, 2 cart id, 3 dead flag, 4 birth time

PTVL_MAP = 1014
PTVL_DEST = { 1014, 1498, 3500 }      -- Luong Thao Quan (south of Dong Quan, BFS 350 cells from the Tieu Su)
PTVL_TIEU_DEST = { 1019, 1609, 2954 } -- Tong Tieu Dau (Tuyet Long linh)
PTVL_CART_TPL = 556                   -- VNG "luong huong xa" (grain cart, Kind 8 -> forced to 0)
PTVL_BANDIT_TPL = 979                 -- VNG "han phi" (bandit, Kind 0 camp 5)
PTVL_TIME = 900
PTVL_DAILY = 6
PTVL_MINLV = 20
PTVL_ABSENT_MAX = 120
