	[2] = "Xe \174\183 b\222 ph\184 h\241y! Chuy\213n \184p v\203n th\202t b\185i.",
	[3] = "Qu\184 th\234i gian \184p v\203n! Chuy\213n \184p v\203n th\202t b\185i.",
	[4] = "Ng\173\172i \174\183 h\241y chuy\213n \184p v\203n.",
	[5] = "Ng\173\172i b\225 xe qu\184 l\169u, xe \174\183 b\222 c\173\237p m\202t! Chuy\213n \184p v\203n th\202t b\185i.",
	[6] = "Chuy\213n \184p v\203n tr\173\237c \174\183 th\202t b\185i (xe b\222 m\202t).",
}

function PTVL_N(v)
	if v == nil then return 0 end
	v = floor(v)
	if v < 0 then v = v + 4294967296 end
	return mod(v, 2000000000)
end

function PTVL_Now()
	if LocalSystemTime then return LocalSystemTime() end
	return floor(GetGameTime() / 18)
end

function PTVL_Day()
	return floor(PTVL_Now() / 86400)
end

function PTVL_Dist2(x1, y1, x2, y2)
	local dx = x1 - x2
	local dy = y1 - y2
	return dx * dx + dy * dy
end

function PTVL_Alive(npc)
	if not npc or npc <= 0 then return nil end
	local w, x, y = GetNpcPos(npc)
	if x and x > 0 and y and y > 0 then return 1 end
	return nil
end

function PTVL_Is(npc, magic, id)
	if not npc or npc <= 0 then return nil end
	if GetNpcParam(npc, 0) ~= magic then return nil end
	if PTVL_N(GetNpcID(npc)) ~= id then return nil end
	return 1
end

function PTVL_Clamp(v, a, b)
	if v < a then return a end
	if v > b then return b end
	return v
end

function PTVL_Min(sec)
	if sec < 0 then sec = 0 end
	return floor((sec + 59) / 60)
end

-- binds PlayerIndex to the cart owner (timer / death contexts only)
function PTVL_BindOwner(npc)
	local pi = GetNpcParam(npc, 1)
	if not pi or pi <= 0 then return nil end
	PlayerIndex = pi
	local nm = GetName()
	if nm == nil or nm == "" then return nil end
	if PTVL_N(GetUUID()) ~= GetNpcParam(npc, 2) then return nil end
	return 1
end

-- the bound player still has this cart in his tasks
function PTVL_OwnerHasCart(npc)
	local id = PTVL_N(GetNpcID(npc))
	if GetNpcParam(npc, 9) == 2 then
		return GetTask(PTVL_T_VTCART) == npc and GetTask(PTVL_T_VTCARTID) == id
	end
	return GetTask(PTVL_T_STATE) == 1 and GetTask(PTVL_T_CART) == npc and GetTask(PTVL_T_CARTID) == id
end

function PTVL_ClearVL()
	SetTask(PTVL_T_STATE, 0)
	SetTask(PTVL_T_CART, 0)
	SetTask(PTVL_T_CARTID, 0)
	SetTask(PTVL_T_DEADLINE, 0)
	SetTask(PTVL_T_MODE, 0)
end

function PTVL_ClearVT()
	SetTask(PTVL_T_VTCART, 0)
	SetTask(PTVL_T_VTCARTID, 0)
end

function PTVL_Runs()
	local d = PTVL_Day()
	if GetTask(PTVL_T_DAY) ~= d then
		SetTask(PTVL_T_DAY, d)
		SetTask(PTVL_T_RUNS, 0)
	end
	return GetTask(PTVL_T_RUNS)
end

-- 1 when the player escorts a live Van Luong cart; clears a stale state (cart lost, server restart)
function PTVL_VLState()
	if GetTask(PTVL_T_STATE) ~= 1 then return 0 end
	local cart = GetTask(PTVL_T_CART)
	if PTVL_Is(cart, PTVL_MG_CART, GetTask(PTVL_T_CARTID)) and PTVL_Alive(cart) then return 1 end
	PTVL_ClearVL()
	SetTask(PTVL_T_LAST, 6)
	Msg2Player(PTVL_LASTMSG[6])
	return 0
end

function PTVL_VTState()
	local cart = GetTask(PTVL_T_VTCART)
	if cart <= 0 then return 0 end
	if PTVL_Is(cart, PTVL_MG_TIEU, GetTask(PTVL_T_VTCARTID)) and PTVL_Alive(cart) then return 1 end
	PTVL_ClearVT()
	return 0
end

-- cart NPC: parameters + timer (both kinds). Caller context: the owner is PlayerIndex.
function PTVL_SetupCart(npc, kind, mode, seconds, dest, ci)
	local w, x, y = GetNpcPos(npc)
	local lv = GetLevel()
	SetNpcKind(npc, 0)
	SetNpcRevTime(npc, 18)
	SetNpcLife(npc, 3000 + lv * 600)
	if kind == 2 then
		SetNpcParam(npc, 0, PTVL_MG_TIEU)
	else
		SetNpcParam(npc, 0, PTVL_MG_CART)
	end
	SetNpcParam(npc, 1, PlayerIndex)
	SetNpcParam(npc, 2, PTVL_N(GetUUID()))
	SetNpcParam(npc, 3, PTVL_Now() + seconds)
	SetNpcParam(npc, 4, 0)
	SetNpcParam(npc, 5, PTVL_Dist2(x, y, dest[2], dest[3]))
	SetNpcParam(npc, 6, 0)
	SetNpcParam(npc, 7, x)
	SetNpcParam(npc, 8, y)
	SetNpcParam(npc, 9, kind)
	SetNpcParam(npc, 10, mode)
	SetNpcParam(npc, 11, ci)
	SetNpcParam(npc, 12, 0)
	SetNpcParam(npc, 13, dest[2])
	SetNpcParam(npc, 14, dest[3])
	SetNpcParam(npc, 15, 0)
	if ci > 0 then
		SetNpcTimer(npc, PTVL_SCRIPT, 2)
	else
		SetNpcTimer(npc, PTVL_SCRIPT, 1)
	end
end

-- Van Luong: spawn the grain cart next to the player. Returns cart npc, siege index.
function PTVL_SpawnCart(mode)
	local w, x, y = GetWorldPos()
	local sw = SubWorldID2Idx(w)
	if not sw or sw < 0 then return 0, 0 end
	local cx = x + 2
	local cy = y + 2
	local npc = 0
	local ci = 0
	if NewSiegeWeapon and SendCarriage and GetSiegeWeaponNpcIndex then
		ci = NewSiegeWeapon(w, cx * 32, cy * 32, PTVL_CART_TPL)
		if ci and ci > 0 then
			npc = GetSiegeWeaponNpcIndex(ci)
			if not npc or npc <= 0 or SendCarriage(ci, GetName(), 1, PTVL_TIME) <= 0 then
				if DeleteSiegeWeapon then DeleteSiegeWeapon(ci) end
				npc = 0
				ci = 0
			end
		else
			ci = 0
		end
	end
	if npc <= 0 then
		npc = AddNpc(PTVL_CART_TPL, 1, sw, cx * 32, cy * 32, 0)
		if not npc or npc <= 0 then return 0, 0 end
		SetNpcKind(npc, 0)
		SetNpcCurCamp(npc, GetCurCamp())
	end
	SetNpcName(npc, PTVL_NAME_CART)
	SetNpcScript(npc, PTVL_SCRIPT)
	PTVL_SetupCart(npc, 1, mode, PTVL_TIME, PTVL_DEST, ci)
	return npc, ci
end

-- Van Tieu (VNG scripts patched in ptfix): called right after SendCarriage, PlayerIndex = owner.
function PTVL_AttachTieu(npc, seconds)
	if not npc or npc <= 0 then return end
	local ci = 0
	if GetSiegeWeaponIndexByNpcIndex then ci = GetSiegeWeaponIndexByNpcIndex(npc) or 0 end
	if not seconds or seconds <= 0 then seconds = 1800 end
	PTVL_SetupCart(npc, 2, 2, seconds, PTVL_TIEU_DEST, ci)
	SetTask(PTVL_T_VTCART, npc)
	SetTask(PTVL_T_VTCARTID, PTVL_N(GetNpcID(npc)))
	SetTask(PTVL_T_VTKILLS, 0)
	Msg2Player("H\233 t\232ng <color=yellow>xe ti\170u<color> \174\213n <color=yellow>T\230ng Ti\170u \167\199u<color> \235 Tuy\214t Long L\220nh (" .. PTVL_TIEU_DEST[2] .. "/" .. PTVL_TIEU_DEST[3] .. "). S\172n t\198c s\207 ph\244c k\221ch d\228c \174\173\234ng!")
end

-- removes a live cart (own timer or dialog context only; never while it is dead)
function PTVL_CartRemove(npc)
	local ci = GetNpcParam(npc, 11)
	SetNpcParam(npc, 0, 0)
	if ci and ci > 0 and DeleteSiegeWeapon and GetSiegeWeaponNpcIndex and GetSiegeWeaponNpcIndex(ci) == npc then
		DeleteSiegeWeapon(ci)
	else
		DelNpc(npc)
	end
end

-- marks the run failed (any context); the cart is removed by its timer once alive again
function PTVL_CartFail(npc, reason)
	local mg = GetNpcParam(npc, 0)
	if mg ~= PTVL_MG_CART and mg ~= PTVL_MG_TIEU then return end
	local kind = GetNpcParam(npc, 9)
	SetNpcParam(npc, 0, PTVL_MG_DEAD)
	local old = PlayerIndex
	if PTVL_BindOwner(npc) and PTVL_OwnerHasCart(npc) then
		if kind == 2 then
			PTVL_ClearVT()
			if RestoreCamp then RestoreCamp() end
		else
			PTVL_ClearVL()
		end
		SetTask(PTVL_T_LAST, reason)
		Msg2Player(PTVL_LASTMSG[reason] or PTVL_LASTMSG[6])
		TopMessage(PTVL_LASTMSG[reason] or PTVL_LASTMSG[6])
	end
	PlayerIndex = old
	if kind == 2 then PTVL_TieuLost(npc, reason) end
end

-- Van Tieu 2004 rule (VNG \script\yun_biao\biao_che.lua OnDeath): a destroyed cart leaves a treasure chest
-- (the looter gets a new cart, \script\yun_biao\bao_xiang.lua) for the first 3 deaths, 1 in 2 up to 6.
function PTVL_TieuLost(npc, reason)
	local dc = GetGlobalValue(424)
	local chest = nil
	if reason == 2 then
		if dc < 3 then chest = 1 elseif dc < 6 and random(1, 2) == 1 then chest = 1 end
	end
	if chest then
		local w = GetNpcPos(npc)
		if not w or w <= 0 then w = PTVL_TIEU_DEST[1] end
		local sw = SubWorldID2Idx(w)
		local x = GetNpcParam(npc, 7)
		local y = GetNpcParam(npc, 8)
		if sw and sw >= 0 and x > 0 then
			local c = AddNpc(416, 1, sw, x * 32, y * 32, 0)
			if c and c > 0 then
				SetNpcName(c, "B\182o R\173\172ng Ti\170u Xa")
				SetNpcScript(c, PTVL_CHEST_SCRIPT)
				SetGlobalValue(425, c)
				SetGlobalValue(424, dc + 1)
				return
			end
		end
	end
	SetGlobalValue(422, 0)
	SetGlobalValue(423, 0)
	SetGlobalValue(424, 0)
end

function PTVL_Absent(npc, step)
	local a = GetNpcParam(npc, 6) + step
	SetNpcParam(npc, 6, a)
	if a >= PTVL_ABSENT_MAX then return 1 end
	return nil
end

-- moves the cart after its owner: engine AiMode 12 walks it (only un-stick here), else Lua steps
function PTVL_Follow(npc, x, y, px, py, d2, lx, ly)
	if GetNpcParam(npc, 11) > 0 then
		if d2 > 144 and x == lx and y == ly then
			local s = GetNpcParam(npc, 15) + 1
			if s >= 3 then
				SetNpcPos(npc, px + 1, py + 1)
				s = 0
			end
			SetNpcParam(npc, 15, s)
		else
			SetNpcParam(npc, 15, 0)
		end
		return
	end
	if d2 <= 9 then return end
	local dx = px - x
	local dy = py - y
	if dx > 2 then dx = dx - 2 elseif dx < -2 then dx = dx + 2 else dx = 0 end
	if dy > 2 then dy = dy - 2 elseif dy < -2 then dy = dy + 2 else dy = 0 end
	dx = PTVL_Clamp(dx, -8, 8)
	dy = PTVL_Clamp(dy, -8, 8)
	if dx ~= 0 or dy ~= 0 then SetNpcPos(npc, x + dx, y + dy) end
end

-- ambush waves at 70% and 40% of the distance left (mode 2; Van Tieu always)
function PTVL_Ambush(npc, x, y)
	if GetNpcParam(npc, 10) ~= 2 then return end
	local waves = GetNpcParam(npc, 4)
	if waves >= 2 then return end
	local d0 = GetNpcParam(npc, 5)
	local d2 = PTVL_Dist2(x, y, GetNpcParam(npc, 13), GetNpcParam(npc, 14))
	local th = 49
	if waves == 1 then th = 16 end
	if d2 * 100 > d0 * th then return end
	SetNpcParam(npc, 4, waves + 1)
	PTVL_SpawnBandits(npc, x, y)
end

PTVL_BANDIT_OFS = { { 6, -4 }, { -6, 4 }, { 5, 6 }, { -5, -6 }, { 8, 0 } }

function PTVL_SpawnBandits(npc, x, y)
	local w = GetNpcPos(npc)
	local sw = SubWorldID2Idx(w)
	if not sw or sw < 0 then return 0 end
	local lv = PTVL_Clamp(GetLevel() - 2, 10, 95)
	local n = 3
	if GetTeamSize() > 1 then n = 4 end
	if GetNpcParam(npc, 9) == 2 then n = n + 1 end
	local name = PTVL_NAME_BANDIT
	if GetNpcParam(npc, 9) == 2 then name = PTVL_NAME_BANDIT2 end
	local id = PTVL_N(GetNpcID(npc))
	local made = 0
	local i = 1
	while i <= n do
		local o = PTVL_BANDIT_OFS[i]
		local b = AddNpc(PTVL_BANDIT_TPL, lv, sw, (x + o[1]) * 32, (y + o[2]) * 32, 0)
		if b and b > 0 then
			SetNpcName(b, name)
			SetNpcScript(b, PTVL_SCRIPT)
			SetNpcRevTime(b, 18)
			SetNpcLife(b, 800 + lv * lv)
			SetNpcParam(b, 0, PTVL_MG_BANDIT)
			SetNpcParam(b, 1, npc)
			SetNpcParam(b, 2, id)
			SetNpcParam(b, 3, 0)
			SetNpcParam(b, 4, PTVL_Now())
			SetNpcTimer(b, PTVL_SCRIPT, 3)
			made = made + 1
		end
		i = i + 1
	end
	if made > 0 then
		Msg2Player("<color=red>" .. made .. " " .. name .. "<color> x\171ng ra ch\198n \174\173\234ng! H\183y b\182o v\214 xe!")
		TopMessage(name .. " ph\244c k\221ch! B\182o v\214 xe!")
	end
	return made
end

function PTVL_ArriveHint(npc, x, y)
	if GetNpcParam(npc, 12) == 1 then return end
	if PTVL_Dist2(x, y, GetNpcParam(npc, 13), GetNpcParam(npc, 14)) > 144 then return end
	SetNpcParam(npc, 12, 1)
	if GetNpcParam(npc, 9) == 2 then
		Msg2Player("Xe ti\170u \174\183 \174\213n n\172i, h\183y b\184o v\237i <color=yellow>T\230ng Ti\170u \167\199u<color>.")
	else
		Msg2Player("Xe l\173\172ng \174\183 \174\213n n\172i, h\183y b\184o v\237i <color=yellow>L\173\172ng Th\182o Quan<color>.")
	end
end

-- cart timer (OnTimer of vl_core.lua)
function PTVL_CartTick(npc)
	local mg = GetNpcParam(npc, 0)
	local w, x, y = GetNpcPos(npc)
	local alive = x and x > 0
	if mg == PTVL_MG_DEAD then
		if alive then PTVL_CartRemove(npc) return end
		SetNpcTimer(npc, PTVL_SCRIPT, 1)
		return
	end
	if not alive then
		PTVL_CartFail(npc, 2)
		SetNpcTimer(npc, PTVL_SCRIPT, 1)
		return
	end
	local step = 1
	if GetNpcParam(npc, 11) > 0 then step = 2 end
	if PTVL_Now() > GetNpcParam(npc, 3) then
		PTVL_CartFail(npc, 3)
		PTVL_CartRemove(npc)
		return
	end
	local lx = GetNpcParam(npc, 7)
	local ly = GetNpcParam(npc, 8)
	SetNpcParam(npc, 7, x)
	SetNpcParam(npc, 8, y)
	local gone = nil
	if PTVL_BindOwner(npc) and PTVL_OwnerHasCart(npc) then
		local pw, px, py = GetWorldPos()
		local d2 = PTVL_Dist2(x, y, px, py)
		if pw == w and d2 <= 3600 then
			SetNpcParam(npc, 6, 0)
			PTVL_Follow(npc, x, y, px, py, d2, lx, ly)
			PTVL_Ambush(npc, x, y)
			PTVL_ArriveHint(npc, x, y)
		else
			gone = PTVL_Absent(npc, step)
		end
	else
		gone = PTVL_Absent(npc, step)
	end
	if gone then
		PTVL_CartFail(npc, 5)
		PTVL_CartRemove(npc)
		return
	end
	SetNpcTimer(npc, PTVL_SCRIPT, step)
end

-- bandit timer: leaves when its cart is gone, after 10 minutes, or once revived after a death
function PTVL_BanditTick(npc)
	local w, x, y = GetNpcPos(npc)
	if not x or x <= 0 then
		SetNpcTimer(npc, PTVL_SCRIPT, 2)
		return
	end
	local gone = GetNpcParam(npc, 3) == 1
	if not gone then
		local cart = GetNpcParam(npc, 1)
		local cm = GetNpcParam(cart, 0)
		if (cm ~= PTVL_MG_CART and cm ~= PTVL_MG_TIEU) or PTVL_N(GetNpcID(cart)) ~= GetNpcParam(npc, 2) then gone = 1 end
	end
	if not gone and PTVL_Now() - GetNpcParam(npc, 4) > 600 then gone = 1 end
	if gone then
		SetNpcParam(npc, 0, 0)
		DelNpc(npc)
		return
	end
	SetNpcTimer(npc, PTVL_SCRIPT, 3)
end

-- a bandit died (LastDamage: PlayerIndex = killer, may be a teammate or a bot)
function PTVL_BanditKilled(npc)
	if GetNpcParam(npc, 0) ~= PTVL_MG_BANDIT or GetNpcParam(npc, 3) == 1 then return end
	SetNpcParam(npc, 3, 1)
	local cart = GetNpcParam(npc, 1)
	local old = PlayerIndex
	local cm = GetNpcParam(cart, 0)
	if (cm == PTVL_MG_CART or cm == PTVL_MG_TIEU) and PTVL_N(GetNpcID(cart)) == GetNpcParam(npc, 2) then
		if PTVL_BindOwner(cart) and PTVL_OwnerHasCart(cart) then
			local t = PTVL_T_KILLS
			if GetNpcParam(cart, 9) == 2 then t = PTVL_T_VTKILLS end
			SetTask(t, GetTask(t) + 1)
		end
	end
	PlayerIndex = old
	if old and old > 0 then Msg2Player("\167\183 h\185 m\233t t\170n c\173\237p.") end
end

-- Revive of a cart or a bandit (ActionScript). SetNpcScript on a Kind 0 NPC also calls Revive: params are
-- still 0 then, so nothing happens.
function PTVL_OnRevive(npc)
	local mg = GetNpcParam(npc, 0)
	if mg == PTVL_MG_CART or mg == PTVL_MG_TIEU then
		PTVL_CartFail(npc, 2)
		SetNpcTimer(npc, PTVL_SCRIPT, 1)
	elseif mg == PTVL_MG_DEAD then
		SetNpcTimer(npc, PTVL_SCRIPT, 1)
	elseif mg == PTVL_MG_BANDIT then
		SetNpcParam(npc, 3, 1)
		SetNpcTimer(npc, PTVL_SCRIPT, 1)
	end
end

-- cart died (DeathSelf with the engine build, LastDamage when a player killed it)
function PTVL_OnCartDown(npc)
	local mg = GetNpcParam(npc, 0)
	if mg == PTVL_MG_CART or mg == PTVL_MG_TIEU then PTVL_CartFail(npc, 2) end
end

-- Van Tieu: the cart must stand next to the Tong Tieu Dau (patched \script\yun_biao\zong_biao_tou.lua)
function PTVL_TieuNear(ci)
	if not GetSiegeWeaponNpcIndex then return 1 end
	local npc = GetSiegeWeaponNpcIndex(ci)
	if not npc or npc <= 0 then return nil end
	local w, x, y = GetNpcPos(npc)
	-- 2026-10-03 (coordinator): no DialogNpcIdx global in the engine; the talking player stands next to
	-- the Tong Tieu Dau, so measure from the player.
	local dw, dx, dy = GetWorldPos()
	if not x or x <= 0 or w ~= dw then return nil end
	if PTVL_Dist2(x, y, dx, dy) > 400 then return nil end
	return 1
end

-- Van Tieu delivered (after the VNG reward of zong_biao_tou.lua): bandit bonus, clear the run
function PTVL_TieuDone()
	local k = GetTask(PTVL_T_VTKILLS)
	if k > 0 then
		local e = k * GetLevel() * 300
		AddOwnExp(e)
		Msg2Player("Th\173\235ng di\214t s\172n t\198c: <color=yellow>" .. e .. "<color> kinh nghi\214m.")
	end
	PTVL_ClearVT()
	SetTask(PTVL_T_VTKILLS, 0)
	SetTask(PTVL_T_LAST, 1)
	if RestoreCamp then RestoreCamp() end
end
